def tile_pattern(grid, background=8):
    """Each connected non-background region's small pattern block tiled over the whole region."""
    from collections import deque
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] == background or seen[i][j]:
                continue
            q = deque([(i, j)]); seen[i][j] = True; cells = []
            while q:
                r, c = q.popleft(); cells.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] != background:
                        seen[nr][nc] = True; q.append((nr, nc))
            rs = [r for r, _ in cells]; cs = [c for _, c in cells]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            nz = [(r, c) for r, c in cells if grid[r][c] != 0]
            if not nz:
                continue
            pr0 = min(r for r, _ in nz); pr1 = max(r for r, _ in nz)
            pc0 = min(c for _, c in nz); pc1 = max(c for _, c in nz)
            ph, pw = pr1 - pr0 + 1, pc1 - pc0 + 1
            pat = [[grid[pr0 + a][pc0 + b] for b in range(pw)] for a in range(ph)]
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = pat[(r - pr0) % ph][(c - pc0) % pw]
    return out
''')
